func priorityColor(t Task) string {
	if t.PriorityColor != "" {
		return t.PriorityColor
	}
	switch t.Priority {
	case "High":
		return "red"
	case "Medium":
		return "yellow"
	case "Low":
		return "blue"
	}
	return ""
}

